{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Clopenthixol, the closest analogue sharing the chlorinated thioxanthene core and propylidene linker, has an absolute oral bioavailability of 40-60% in humans, directly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Cyclobenzaprine, which shares the dimethylaminopropylidene side chain and tricyclic lipophilic core, has mean oral bioavailability of 33-55% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Doxepin, with the same dimethylaminopropylidene side chain and tricyclic scaffold, has absolute oral bioavailability of about 25-29%, still above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Flupenthixol, a thioxanthene with the same propylidene attachment and a halogen substituent, shows oral bioavailability around 40-60%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Zotepine, which has a dimethylamino side chain and a chlorinated sulfur-containing tricyclic but a different dibenzothiepine/ether scaffold, shows low oral bioavailability (7-13%); this is contradictory but less transferable to the thioxanthene query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The most transferable experimental evidence—clopenthixol and flupenthixol (thioxanthenes) and cyclobenzaprine/doxepin (dimethylaminopropylidene tricyclics)—all show oral bioavailability above 20%. The low-bioavailability examples are structurally more distant or have different side-chain scaffolds, so the balance supports a high F >= 20% prediction.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for chlorprothixene itself is provided.",
    "First-pass metabolism and solubility data for the exact query are not available; zotepine's low F indicates that sulfur-containing tricyclics can have high first-pass extraction, but its different scaffold limits transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

